package com.waxmes.app.data

import java.util.Date

data class User(val uid: String = "", val displayName: String = "", val avatar: String = "", val color: Long = 0xFF818CF8)
data class Conversation(val id: String = "", var name: String = "", val lastMsg: String = "", val lastActivity: Long = 0, var unread: Int = 0, var avatarUrl: String = "", val color: Long = 0xFF818CF8, var online: Boolean = false, val isGroup: Boolean = false, var otherId: String = "", var isPinned: Boolean = false, var isMuted: Boolean = false, var isArchived: Boolean = false, var pinnedMsgIds: List<String> = emptyList())
data class Message(val id: String = "", val text: String = "", val time: String = "", val senderId: String = "", val type: String = "sent", val image: String = "", val audio: String = "", val video: String = "", val replyTo: String = "", val replyText: String = "", val deleted: Boolean = false, val deletedByMe: Boolean = false, val isForwarded: Boolean = false, val originalSender: String = "", val forwardComment: String = "", val createdAt: Date = Date(), val edited: Boolean = false, val editedTime: String = "")
data class Story(val id: String = "", val authorId: String = "", val authorName: String = "", val authorAvatar: String = "", val authorColor: Long = 0xFF818CF8, val text: String = "", val mediaUrl: String = "", val type: String = "text", val bgColor: String = "#818cf8", val fontFamily: String = "sans", val caption: String = "", val createdAt: Long = 0, val expiresAt: Long = 0, val viewers: List<String> = emptyList())